const deals = $('OpenDeals').first()?.json;
const contacts = $('RecentContacts').first()?.json;

// Detect connection state from upstream HTTP success (credentials live in n8n now)
const dealsOk = !!deals && Array.isArray(deals.results);
const contactsOk = !!contacts && Array.isArray(contacts.results);
const hubspotConnected = dealsOk || contactsOk;

const dealsItems = dealsOk ? deals.results : [];
const contactsItems = contactsOk ? contacts.results : [];

const closedStages = new Set(['closedwon', 'closedlost']);
const pipelineValue = dealsItems
  .filter(d => !closedStages.has((d.properties.dealstage || '').toLowerCase()))
  .reduce((s, d) => s + (parseFloat(d.properties.amount) || 0), 0);

const newLeads = contactsItems.length;

const autoLeads = contactsItems.filter(c => {
  const src = (c.properties.hs_analytics_source || '').toUpperCase();
  return src === 'INTEGRATION' || src === 'API';
}).length;

const sparkline = [];
const now = Date.now();
for (let d = 13; d >= 0; d--) {
  const dayStart = now - (d + 1) * 86400000;
  const dayEnd = now - d * 86400000;
  const dayCount = contactsItems.filter(c => {
    const t = parseInt(c.properties.createdate, 10);
    return t >= dayStart && t < dayEnd;
  }).length;
  sparkline.push(dayCount);
}

return [{
  json: {
    hubspot_connected: hubspotConnected,
    pipeline_value: hubspotConnected ? pipelineValue : null,
    new_leads: hubspotConnected ? newLeads : null,
    auto_leads: hubspotConnected ? autoLeads : null,
    sparkline: hubspotConnected ? sparkline : null,
    period_label: 'Last 14 days'
  }
}];
